// parseTLSClientHello parses a raw TLS ClientHello packet and extracts JA4 data
// This is a simplified parser for test purposes
func parseTLSClientHello(payload []byte, protocol byte) (*ClientHelloData, error) {
	if len(payload) < 5 {
		return nil, nil
	}

	// Check for TLS handshake (0x16)
	if payload[0] != 0x16 {
		return nil, nil
	}

	// Skip record header (5 bytes)
	offset := 5

	// Check for ClientHello (0x01)
	if len(payload) <= offset || payload[offset] != 0x01 {
		return nil, nil
	}
	offset++

	// Skip handshake length (3 bytes)
	if len(payload) < offset+3 {
		return nil, nil
	}
	offset += 3

	// Read version (2 bytes)
	if len(payload) < offset+2 {
		return nil, nil
	}
	version := binary.BigEndian.Uint16(payload[offset:])
	offset += 2

	// Skip random (32 bytes)
	offset += 32

	// Session ID length
	if len(payload) <= offset {
		return nil, nil
	}
	sessionIDLen := int(payload[offset])
	offset++
	offset += sessionIDLen

	// Cipher suites length (2 bytes)
	if len(payload) < offset+2 {
		return nil, nil
	}
	cipherSuitesLen := int(binary.BigEndian.Uint16(payload[offset:]))
	offset += 2

	// Parse cipher suites
	var cipherSuites []uint16
	if len(payload) < offset+cipherSuitesLen {
		return nil, nil
	}
	for i := 0; i < cipherSuitesLen; i += 2 {
		if offset+i+2 > len(payload) {
			break
		}
		cs := binary.BigEndian.Uint16(payload[offset+i:])
		cipherSuites = append(cipherSuites, cs)
	}
	offset += cipherSuitesLen

	// Compression methods length
	if len(payload) <= offset {
		return nil, nil
	}
	compressionLen := int(payload[offset])
	offset++
	offset += compressionLen

	// Extensions length (2 bytes)
	if len(payload) < offset+2 {
		return nil, nil
	}
	extensionsLen := int(binary.BigEndian.Uint16(payload[offset:]))
	offset += 2

	// Parse extensions
	var extensions []uint16
	var sni string
	var alpns []string
	var supportedVers uint16
	var signatureAlgorithms []uint16
	extEnd := offset + extensionsLen
	if extEnd > len(payload) {
		extEnd = len(payload)
	}

	for offset < extEnd {
		if offset+4 > len(payload) {
			break
		}
		extType := binary.BigEndian.Uint16(payload[offset:])
		extLen := int(binary.BigEndian.Uint16(payload[offset+2:]))
		offset += 4

		extensions = append(extensions, extType)

		if offset+extLen > len(payload) {
			break
		}
		extData := payload[offset : offset+extLen]

		// Parse SNI (type 0)
		if extType == 0 && extLen > 5 {
			// Skip list length (2) + type (1) + name length (2)
			nameLen := int(binary.BigEndian.Uint16(extData[3:]))
			if 5+nameLen <= len(extData) {
				sni = string(extData[5 : 5+nameLen])
			}
		}

		// Parse ALPN (type 16)
		if extType == 16 && extLen > 2 {
			alpnListLen := int(binary.BigEndian.Uint16(extData))
			alpnOffset := 2
			for alpnOffset < 2+alpnListLen && alpnOffset < len(extData) {
				alpnLen := int(extData[alpnOffset])
				alpnOffset++
				if alpnOffset+alpnLen <= len(extData) {
					alpns = append(alpns, string(extData[alpnOffset:alpnOffset+alpnLen]))
				}
				alpnOffset += alpnLen
			}
		}

		// Parse signature_algorithms (type 13)
		if extType == 13 && extLen >= 2 {
			sigListLen := int(binary.BigEndian.Uint16(extData))
			for i := 2; i+1 < 2+sigListLen && i+1 < len(extData); i += 2 {
				sig := binary.BigEndian.Uint16(extData[i:])
				signatureAlgorithms = append(signatureAlgorithms, sig)
			}
		}

		// Parse supported_versions (type 43)
		if extType == 43 && extLen > 0 {
			// First byte is list length
			listLen := int(extData[0])
			// Find highest non-GREASE version
			for i := 1; i < 1+listLen && i+1 < len(extData); i += 2 {
				v := binary.BigEndian.Uint16(extData[i:])
				if !isGrease(v) && v > supportedVers {
					supportedVers = v
				}
			}
		}

		offset += extLen
	}

	return &ClientHelloData{
		Version:             version,
		CipherSuites:        cipherSuites,
		Extensions:          extensions,
		SNI:                 sni,
		ALPNs:               alpns,
		SupportedVers:       supportedVers,
		IsQUIC:              protocol == 'q',
		SignatureAlgorithms: signatureAlgorithms,
	}, nil
}

// parseTLSServerHello parses a raw TLS ServerHello packet and extracts JA4S data
func parseTLSServerHello(payload []byte, protocol byte) (*ServerHelloData, error) {
	if len(payload) < 5 {
		return nil, nil
	}

	// Check for TLS handshake (0x16)
	if payload[0] != 0x16 {
		return nil, nil
	}

	// Skip record header (5 bytes)
	offset := 5

	// Check for ServerHello (0x02)
	if len(payload) <= offset || payload[offset] != 0x02 {
		return nil, nil
	}
	offset++

	// Skip handshake length (3 bytes)
	if len(payload) < offset+3 {
		return nil, nil
	}
	offset += 3

	// Read version (2 bytes)
	if len(payload) < offset+2 {
		return nil, nil
	}
	version := binary.BigEndian.Uint16(payload[offset:])
	offset += 2

	// Skip random (32 bytes)
	offset += 32

	// Session ID length
	if len(payload) <= offset {
		return nil, nil
	}
	sessionIDLen := int(payload[offset])
	offset++
	offset += sessionIDLen

	// Cipher suite (2 bytes)
	if len(payload) < offset+2 {
		return nil, nil
	}
	cipherSuite := binary.BigEndian.Uint16(payload[offset:])
	offset += 2

	// Compression method (1 byte)
	if len(payload) <= offset {
		return nil, nil
	}
	offset++

	// Extensions length (2 bytes)
	var extensions []uint16
	var supportedVers uint16
	var alpn string
	if len(payload) >= offset+2 {
		extensionsLen := int(binary.BigEndian.Uint16(payload[offset:]))
		offset += 2

		extEnd := offset + extensionsLen
		if extEnd > len(payload) {
			extEnd = len(payload)
		}

		for offset < extEnd {
			if offset+4 > len(payload) {
				break
			}
			extType := binary.BigEndian.Uint16(payload[offset:])
			extLen := int(binary.BigEndian.Uint16(payload[offset+2:]))
			offset += 4

			extensions = append(extensions, extType)

			if offset+extLen > len(payload) {
				break
			}
			extData := payload[offset : offset+extLen]

			// Parse ALPN (type 16) - ServerHello has selected ALPN
			if extType == 16 && extLen > 2 {
				alpnListLen := int(binary.BigEndian.Uint16(extData))
				if alpnListLen > 0 && len(extData) > 2 {
					alpnStrLen := int(extData[2])
					if 3+alpnStrLen <= len(extData) {
						alpn = string(extData[3 : 3+alpnStrLen])
					}
				}
			}

			// Parse supported_versions (type 43)
			if extType == 43 && extLen >= 2 {
				supportedVers = binary.BigEndian.Uint16(extData)
			}

			offset += extLen
		}
	}

	return &ServerHelloData{
		Version:       version,
		CipherSuite:   cipherSuite,
		Extensions:    extensions,
		SupportedVers: supportedVers,
		IsQUIC:        protocol == 'q',
		ALPN:          alpn,
	}, nil
}

